INSERT INTO DimDate (SK_DateID, DateValue, DateDesc, CalendarYearID, CalendarYearDesc, CalendarQtrID, CalendarQtrDesc, CalendarMonthID, CalendarMonthDesc, CalendarWeekID, CalendarWeekDesc, DayOfWeekNum, DayOfWeekDesc, FiscalYearID, FiscalYearDesc, FiscalQtrID, FiscalQtrDesc, HolidayFlag) SELECT CAST(Date.SK_DateID AS INT) AS SK_DateID, CAST(DateValue AS DATE) AS DateValue, CAST(Date.DateDesc AS TEXT) AS DateDesc, CAST(COALESCE(CAST(CalendarYearID AS DECIMAL(4)), 0) AS DECIMAL(4, 0)) AS CalendarYearID, CAST(Date.CalendarYearDesc AS TEXT) AS CalendarYearDesc, CAST(COALESCE(TRY_CAST(Date.CalendarQtrID AS DECIMAL(5, 0)), 0) AS DECIMAL(5, 0)) AS CalendarQtrID, CAST(Date.CalendarQtrDesc AS TEXT) AS CalendarQtrDesc, CAST(COALESCE(TRY_CAST(Date.CalendarMonthID AS DECIMAL(6, 0)), 0) AS DECIMAL(6, 0)) AS CalendarMonthID, CAST(Date.CalendarMonthDesc AS TEXT) AS CalendarMonthDesc, CAST(COALESCE(Date.CalendarWeekID, 0) AS DECIMAL(6)) AS CalendarWeekID, CAST(Date.CalendarWeekDesc AS TEXT) AS CalendarWeekDesc, CAST(COALESCE(CAST(NULLIF(TRIM(CAST(Date.DayOfWeekNum AS TEXT)), '') AS INT), 0) AS DECIMAL(1, 0)) AS DayOfWeekNum, CAST(Date.DayOfWeekDesc AS TEXT) AS DayOfWeekDesc, CAST(COALESCE(Date.FiscalYearID, 0) AS DECIMAL(4)) AS FiscalYearID, CAST(Date.FiscalYearDesc AS TEXT) AS FiscalYearDesc, CAST(Date.FiscalQtrID AS DECIMAL(5)) AS FiscalQtrID, CAST(Date.FiscalQtrDesc AS TEXT) AS FiscalQtrDesc, CAST(Date.HolidayFlag AS BOOLEAN) AS HolidayFlag FROM Source.Date;
